<template><div class="panel"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><b>员工账号</b><el-button type="primary" @click="dialog=true">新增账号</el-button></div><el-table :data="rows" border><el-table-column prop="username" label="账号"/><el-table-column prop="display_name" label="姓名"/><el-table-column prop="role" label="角色"><template #default="s"><el-tag>{{s.row.role==='admin'?'管理员':'员工'}}</el-tag></template></el-table-column><el-table-column prop="status" label="状态"><template #default="s"><el-switch :model-value="!!s.row.status" @change="v=>changeStatus(s.row,v)"/></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="resetPwd(s.row)">重置密码</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="新增账号" width="420px"><el-form><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" style="width:100%"><el-option label="员工" value="employee"/><el-option label="管理员" value="admin"/></el-select></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" show-password/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog></div></template>
<script setup>import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '../utils';const rows=ref([]),dialog=ref(false),form=reactive({username:'',displayName:'',role:'employee',password:''});async function load(){rows.value=(await api.get('/auth/users')).data.items}async function create(){try{await api.post('/auth/users',form);ElMessage.success('账号创建成功');dialog.value=false;Object.assign(form,{username:'',displayName:'',role:'employee',password:''});load()}catch(e){ElMessage.error(e.response?.data?.message||'创建失败')}}async function changeStatus(r,v){try{await api.patch(`/auth/users/${r.id}/status`,{status:v});ElMessage.success('状态已更新')}catch(e){ElMessage.error('更新失败');load()}}async function resetPwd(r){const p=await new Promise(resolve=>{ElMessageBox.prompt(`为 ${r.username} 设置新密码`,'重置密码',{inputType:'password'}).then(x=>resolve(x.value)).catch(()=>resolve(null))});if(p===null)return;try{await api.patch(`/auth/users/${r.id}/password`,{password:p});ElMessage.success('密码已重置')}catch(e){ElMessage.error(e.response?.data?.message||'重置失败')}}onMounted(load)</script>
